const eventMap = new Map();
for (const [chapterId, chapterRoot] of Object.entries(chapterRoots)) {
  const manifest = JSON.parse(await readFile(new URL(`${chapterRoot}/event_manifest.json`, root), "utf8"));
  for (const event of manifest) eventMap.set(event.chapter_event_id, { ...event, chapterId, chapterRoot });
}

