function evidenceFor(eventId) {
  const event = eventMap.get(eventId);
  if (!event) throw new Error(`Evento desconocido: ${eventId}`);
  const evidence = [{
    chapter_id: event.chapterId,
    event_id: eventId,
    timestamp: event.timestamp,
    image: `${event.chapterRoot}/${event.chapter_full_image}`,
    detail_crop: event.chapter_detail_crop ? `${event.chapterRoot}/${event.chapter_detail_crop}` : "",
    transcript: `${event.chapterRoot}/transcript_raw.txt`
  }];
  return evidence;
}

function row(input) {
  const merged = { ...defaults, ...input };
  merged.event_ids = Array.isArray(input.event_ids) ? input.event_ids : [input.event_ids];
  merged.timestamps = merged.event_ids.map((id) => eventMap.get(id)?.timestamp).filter(Boolean);
  merged.source_evidence = merged.event_ids.flatMap(evidenceFor);
  merged.acceptance_criteria ||= [
    merged.expected_behavior,
    "Persiste después de recargar cuando la acción modifica datos.",
    "Respeta rol y organización.",
    "Tiene prueba automatizada específica y prueba de navegador cuando corresponde."
  ];
  if (!allowedStatuses.includes(merged.status)) throw new Error(`Estado inválido en ${merged.requirement_id}: ${merged.status}`);
  return merged;
}

